10	/** Game families whose OsTemplate rows are managed on the Game servers panel. */
11	
12	const schema = z.object({
13	  id: z.string().min(1),
14	  minRamMB: z.coerce.number().int().min(256).max(262144),
15	  minDiskGB: z.coerce.number().int().min(1).max(4096),
16	  setupScript: z.string().max(20000).optional(),
17	});
