19	/**
20	 * Save a game image (OsTemplate) — RAM/disk minimums, setup script and active
21	 * flag. ADMIN-only, audit-logged. Only operates on APPLICATION-category rows in
22	 * a known game family, so it can't be pointed at OS templates.
23	 */
24	export async function saveGameImage(
25	  prev: { ok?: boolean; error?: string } | undefined,
26	  formData: FormData,
27	): Promise<{ ok?: boolean; error?: string }> {
28	  const admin = await requireAdmin();
29	
30	  const parsed = schema.safeParse({
31	    id: formData.get("id"),
32	    minRamMB: formData.get("minRamMB"),
33	    minDiskGB: formData.get("minDiskGB"),
34	    setupScript: formData.get("setupScript") ?? "",
35	  });
36	  if (!parsed.success) return { error: "Check the RAM/disk values — RAM ≥ 256 MB, disk ≥ 1 GB." };
37	
38	  const active = formData.get("active") === "on";
39	  const { id, minRamMB, minDiskGB } = parsed.data;
40	  const setupScript = (parsed.data.setupScript ?? "").trim();
41	
42	  const image = await db.osTemplate.findUnique({ where: { id } });
43	  if (!image) return { error: "Image not found." };
44	  if (image.category !== "APPLICATION" || !GAME_FAMILIES.includes(image.family as import("./games").GameFamily)) {
45	    return { error: "This image is not a managed game image." };
46	  }
47	
48	  await db.osTemplate.update({
49	    where: { id },
50	    data: { minRamMB, minDiskGB, active, setupScript: setupScript || null },
51	  });
52	  await db.auditLog.create({
53	    data: {
54	      userId: admin.id,
55	      action: "games.saveImage",
56	      detail: `${image.name} (${image.family}): ${minRamMB}MB / ${minDiskGB}GB, active=${active}`,
57	    },
58	  });
59	
60	  revalidatePath("/admin/games");
61	  return { ok: true };
62	}
