1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { revalidatePath } from "next/cache";
5	import type { User } from "@prisma/client";
6	import { z } from "zod";
7	import { db } from "./db";
8	import { requireUser, assertNotImpersonating } from "./auth";
9	import { requireArea } from "./rbac";
10	import { GAME_FAMILIES } from "./games";
11	import { emailVerificationError } from "./email-verification";
12	import {
13	  placeGameOrder,
14	  gameOrderQuote,
15	  gameOrderGate,
16	  gameIntentFromFormData,
17	  GameOrderError,
18	  type GameOrderIntent,
19	  type GameOrderPrice,
20	} from "./game-order";
21	import { walletSplit } from "./wallet-split";
22	import { createGameOrderPaymentSession, type EmbeddedCheckout } from "./stripe";
23	
24	/**
25	 * Game servers as a distinct product. A `GamePlan` is one pricing tier for one
26	 * game (Minecraft 2 GB / 10 slots, etc). Admins (billing area) manage the
27	 * catalogue; customers order a tier, which provisions a VM sized by the tier's
28	 * base VPS Plan running the game's OsTemplate image.
29	 *
30	 * This module owns:
31	 *   - adminSaveGamePlan / adminToggleGamePlan / adminDeleteGamePlan (CRUD)
32	 *   - orderGameServer (customer deploy) — mirrors the VPS deploy path in
33	 *     lib/actions.ts payAndDeploy / lib/order.ts placeOrder.
34	 */
35	
36	type Result = { error?: string; ok?: boolean };
37	
38	// ---------- Admin CRUD ----------
39	
40	const planSchema = z.object({
41	  id: z.string().optional(),
42	  gameFamily: z.enum(GAME_FAMILIES),
43	  name: z.string().min(2).max(80),
44	  ramMB: z.coerce.number().int().min(256).max(262144),
45	  cpuCores: z.coerce.number().int().min(1).max(64),
46	  diskGB: z.coerce.number().int().min(1).max(4096),
47	  slots: z.coerce.number().int().min(1).max(100000).optional(),
48	  priceCents: z.coerce.number().int().min(0).max(100000000),
49	  termMonths: z.coerce.number().int().min(1).max(36),
50	  basePlanId: z.string().min(1),
51	  osTemplateId: z.string().optional(),
52	  sortOrder: z.coerce.number().int().min(0).max(100000),
53	});
54	
55	/**
56	 * Create or update a GamePlan tier. ADMIN/BILLING only, audit-logged. Validates
57	 * the chosen base VPS Plan (sizing source) and the game OsTemplate (must belong
58	 * to the same game family, if provided).
59	 */
60	export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
61	  const admin = await requireArea("billing");
62	
63	  const rawSlots = String(formData.get("slots") ?? "").trim();
64	  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
65	  const parsed = planSchema.safeParse({
66	    id: formData.get("id") || undefined,
67	    gameFamily: formData.get("gameFamily"),
68	    name: formData.get("name"),
69	    ramMB: formData.get("ramMB"),
70	    cpuCores: formData.get("cpuCores"),
71	    diskGB: formData.get("diskGB"),
72	    slots: rawSlots === "" ? undefined : rawSlots,
73	    priceCents: formData.get("priceCents"),
74	    termMonths: formData.get("termMonths"),
75	    basePlanId: formData.get("basePlanId"),
76	    osTemplateId: rawOs === "" ? undefined : rawOs,
77	    sortOrder: formData.get("sortOrder") ?? 0,
78	  });
79	  if (!parsed.success) {
80	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
81	  }
82	  const d = parsed.data;
83	
84	  const base = await db.plan.findUnique({ where: { id: d.basePlanId } });
85	  if (!base) return { error: "Choose a valid base VPS plan for provisioning." };
86	
87	  let osTemplateId: string | null = null;
88	  if (d.osTemplateId) {
89	    const os = await db.osTemplate.findUnique({ where: { id: d.osTemplateId } });
90	    if (!os) return { error: "Selected game image not found." };
91	    if (os.family !== d.gameFamily) {
92	      return { error: `That image belongs to "${os.family}", not "${d.gameFamily}".` };
93	    }
94	    osTemplateId = os.id;
95	  }
96	
97	  const featured = formData.get("featured") === "on";
98	  const active = formData.get("active") === "on";
99	
100	  const data = {
101	    gameFamily: d.gameFamily,
102	    name: d.name.trim(),
103	    ramMB: d.ramMB,
104	    cpuCores: d.cpuCores,
105	    diskGB: d.diskGB,
106	    slots: d.slots ?? null,
107	    priceCents: d.priceCents,
108	    termMonths: d.termMonths,
109	    basePlanId: d.basePlanId,
110	    osTemplateId,
111	    featured,
112	    active,
113	    sortOrder: d.sortOrder,
114	  };
115	
116	  if (d.id) {
117	    const existing = await db.gamePlan.findUnique({ where: { id: d.id } });
118	    if (!existing) return { error: "Tier not found." };
119	    await db.gamePlan.update({ where: { id: d.id }, data });
120	  } else {
121	    await db.gamePlan.create({ data });
122	  }
123	
124	  await db.auditLog.create({
125	    data: {
126	      userId: admin.id,
127	      action: d.id ? "gameplan.update" : "gameplan.create",
128	      detail: `${data.gameFamily} — ${data.name} (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
129	    },
130	  });
131	  revalidatePath("/admin/game-plans");
132	  return { ok: true };
133	}
134	
135	/** Flip a tier's active flag. */
136	export async function adminToggleGamePlan(id: string): Promise<void> {
137	  const admin = await requireArea("billing");
138	  const gp = await db.gamePlan.findUnique({ where: { id } });
139	  if (!gp) return;
140	  await db.gamePlan.update({ where: { id }, data: { active: !gp.active } });
141	  await db.auditLog.create({
142	    data: { userId: admin.id, action: "gameplan.toggle", detail: `${gp.name} → active=${!gp.active}` },
143	  });
144	  revalidatePath("/admin/game-plans");
145	}
146	
147	/** Delete a tier. Refused while servers reference it. */
148	export async function adminDeleteGamePlan(id: string): Promise<Result> {
149	  const admin = await requireArea("billing");
150	  const gp = await db.gamePlan.findUnique({
151	    where: { id },
152	    include: { _count: { select: { servers: true } } },
153	  });
154	  if (!gp) return { error: "Tier not found." };
155	  if (gp._count.servers > 0) {
156	    return { error: `Can't delete — ${gp._count.servers} server(s) use this tier. Disable it instead.` };
157	  }
158	  await db.gamePlan.delete({ where: { id } });
159	  await db.auditLog.create({
160	    data: { userId: admin.id, action: "gameplan.delete", detail: `${gp.gameFamily} — ${gp.name}` },
161	  });
162	  revalidatePath("/admin/game-plans");
163	  return { ok: true };
164	}
165	
166	// ---------- Customer deploy ----------
167	
168	/**
169	 * Feature + capacity gate shared by both game order entry points: the game-servers
170	 * feature can be switched off platform-wide (flag), and game servers are Server rows
171	 * too so they count toward the per-user cap. Returns a customer-facing error to
172	 * surface, or null to proceed. The email-verification gate is applied INLINE at each
173	 * entry point so the "consult the gate before taking money" invariant is visible at
174	 * the call site (see test/auth-lockouts.test.ts B4).
175	 *
176	 * The MONEY-CRITICAL guards (plan validity, image, capacity, balance, atomic debit)
177	 * live in `placeGameOrder` (lib/game-order.ts), so the Stripe fulfilment path is
178	 * safe WITHOUT this gate — this only fronts the interactive order actions, exactly
179	 * as `serverLimitError` fronts `payAndDeploy` for VPS.
180	 *
181	 * `gameOrderGate` and `gameIntentFromFormData` now live in lib/game-order.ts (a
182	 * plain module) rather than here — see that file for why: a helper that takes an
183	 * already-authenticated `user` (or does no auth at all) must never be exported
184	 * from a `"use server"` file, since every such export is independently
185	 * network-callable (test/auth-lockouts.test.ts's "HAZARD" suite).
186	 */
187	
188	/**
189	 * Wizard checkout for a game server — the game analogue of `payAndDeploy`, built on
190	 * the SAME audited machinery: it reuses `walletSplit` for the wallet/card split,
191	 * `placeGameOrder` (lib/game-order.ts) as the ONE debit path, and — when a card leg
192	 * is needed — `createGameOrderCheckout` + the shared Stripe fulfilment bus
193	 * (lib/fulfil-checkout.ts) that also settles VPS orders. No new charge path.
194	 *
195	 * MONEY: game bills FULL from month 1 — no first-month-free, no coupon, no VAT
196	 * change. The charge is the DB-fed term price (`gameOrderQuote.chargeCents`), the
197	 * SOLD price is stamped on the Checkout session BEFORE the card is charged, and
198	 * fulfilment settles that exact figure (never re-quoted after the card cleared).
199	 * displayed (wizard) === charged (here) === renewed (renewalCharge).
200	 */
201	export async function payAndDeployGame(
202	  _prev: unknown,
203	  formData: FormData,
204	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
205	  const user = await requireUser();
206	  // Spend path: never move a customer's money while an admin is impersonating them.
207	  // Caught so an impersonating admin sees this message inline instead of a page
208	  // crash — the bare throw used to hit the wizard's generic error screen on
209	  // every payment attempt.
210	  try {
211	    await assertNotImpersonating();
212	  } catch (e) {
213	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
214	  }
215	  // Purchase gate: an unverified address means we cannot reach the person we are
216	  // about to charge (see lib/email-verification.ts). Consulted before any money moves.
217	  const unverified = await emailVerificationError(user);
218	  if (unverified) return { error: unverified };
219	  const gateErr = await gameOrderGate(user);
220	  if (gateErr) return { error: gateErr };
221	
222	  const intent = gameIntentFromFormData(formData);
223	
224	  let quote;
225	  try {
226	    quote = await gameOrderQuote(intent);
227	  } catch (e) {
228	    if (e instanceof GameOrderError) return { error: e.message };
229	    throw e;
230	  }
231	
232	  // The full, DB-fed term price. No promo/coupon/VAT adjustment for game.
233	  const chargeCents = quote.chargeCents;
234	
235	  // Wallet-aware split — the wizard computes the identical split (lib/wallet-split.ts)
236	  // from the same inputs, so what the customer sees === what we charge. `useWallet`
237	  // defaults ON (only "0" turns it off).
238	  const useWallet = formData.get("useWallet") !== "0";
239	  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });
240	
241	  // Card portion is $0 (the wallet covers the whole charge) → provision straight
242	  // away through the audited debit. `placeGameOrder` debits the FULL chargeCents
243	  // from the wallet; its balance check holds because cardCents <= 0 means the
244	  // balance already covers the charge.
245	  if (cardCents <= 0) {
246	    let serverId: string;
247	    try {
248	      serverId = await placeGameOrder(user, intent, null);
249	    } catch (e) {
250	      if (e instanceof GameOrderError) return { error: e.message };
251	      throw e;
252	    }
253	    // Wallet-only is still a real payment — same `?purchase=1` marker the card/
254	    // Stripe path gets via reportPurchase, so ProvisioningOverlay's "just paid"
255	    // success screen shows for this path too.
256	    redirect(`/dashboard/servers/${serverId}?purchase=1`);
257	  }
258	
259	  // Card leg > 0 → charge ONLY the remainder on the card. On payment success the
260	  // confirm/webhook route credits this card amount to the wallet and THEN
261	  // placeGameOrder debits the full chargeCents, so the wallet naturally absorbs the
262	  // applied balance and the card the rest — the wallet is never touched before the
263	  // card clears. The SOLD price is handed over EXPLICITLY (stamped before any
264	  // charge), so a rate change between now and fulfilment can't re-price it.
265	  const sold: GameOrderPrice = { chargeCents };
266	  let checkout: EmbeddedCheckout | null;
267	  try {
268	    checkout = await createGameOrderPaymentSession(user, cardCents, intent, sold);
269	  } catch (e) {
270	    if (e instanceof GameOrderError) return { error: e.message };
271	    throw e;
272	  }
273	  if (!checkout) {
274	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
275	  }
276	  return { checkout };
277	}
278	
279	/**
280	 * Legacy one-click wallet deploy, SUPERSEDED by `payAndDeployGame` + the
281	 * GameDeployWizard. Kept as a thin, wallet-only wrapper over the audited core so any
282	 * remaining caller keeps working: it charges the tier's DB-fed term price from the
283	 * wallet (full price — game has no first-month-free) and never opens a card leg.
284	 */
285	export async function orderGameServer(gamePlanId: string, termMonthsRaw?: number): Promise<Result> {
286	  const user = await requireUser();
287	  await assertNotImpersonating();
288	  // Purchase gate: an unverified address means we cannot reach the person we are
289	  // about to charge (see lib/email-verification.ts).
290	  const unverified = await emailVerificationError(user);
291	  if (unverified) return { error: unverified };
292	  const gateErr = await gameOrderGate(user);
293	  if (gateErr) return { error: gateErr };
294	
295	  let serverId: string;
296	  try {
297	    serverId = await placeGameOrder(user, { gamePlanId, termMonths: Number(termMonthsRaw ?? 1) }, null);
298	  } catch (e) {
299	    if (e instanceof GameOrderError) return { error: e.message };
300	    throw e;
301	  }
302	  redirect(`/dashboard/servers/${serverId}`);
303	}
