981	): Promise<{ ok: true; installed: boolean; hasYamlStorage: boolean } | { ok: false; error: string }> {
982	  try {
983	    const { user, server } = await ownedServer(serverId);
984	    const spec = requireSpec(server);
985	    if (spec.family !== "minecraft") return { ok: false, error: "Roles are only available for Minecraft." };
