991	      const pluginsRes = await runRcon(conn, spec, "plugins");
992	      if (!pluginsRes.ok) return { installed: false, hasYamlStorage: false };
993	      const installed = /luckperms/i.test(stripAnsi(pluginsRes.response));
994	      if (!installed) return { installed: false, hasYamlStorage: false };
995	      const lpDir = await findLpDir(conn, spec);
