1009	    const { user, server } = await ownedServer(serverId);
1010	    const spec = requireSpec(server);
1011	    if (spec.family !== "minecraft") return { ok: false, error: "Roles are only available for Minecraft." };
1012	    if (SANDBOX) return { ok: true };
1013	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
1014	    const res = await withServerSsh(server as SftpServer, async (conn) => {
1015	      const lpDir = await findLpDir(conn, spec);
