1017	      const configPath = `${lpDir}/config.yml`;
1018	      const configRead = await exec(conn, `cat ${JSON.stringify(configPath)}`, 5_000);
1019	      if (configRead.code !== 0) return { ok: false as const, error: "Can't read LuckPerms config." };
1020	      const hasYaml = /^storage-method:\s*yaml\s*$/m.test(configRead.stdout);
1021	      const hasUuidCache = /^use-server-uuid-cache:\s*true\s*$/m.test(configRead.stdout);
