1123	
1124	/**
1125	 * Valid hostname: letters, digits, hyphens, dots. No protocol, no path, no IP,
1126	 * at least 4 chars (shortest: a.co). Max 253 chars per RFC 1035.
1127	 */
1128	const HOSTNAME_RE = /^(?!.*\.\.)(?!-)[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*\.[a-zA-Z]{2,}$/;
1129	const IP_RE = /^\d{1,3}(\.\d{1,3}){3}$/;
1130	
1131	function cleanDomain(raw: string): string {
1132	  let d = raw.trim().toLowerCase();
1133	  // Strip protocol prefix if someone pastes a URL
1134	  d = d.replace(/^https?:\/\//i, "");
1135	  // Strip trailing slash / path
1136	  d = d.replace(/\/.*$/, "");
1137	  return d;
1138	}
1139	
1140	function validateDomain(raw: string): { ok: true; domain: string } | { ok: false; error: string } {
1141	  const domain = cleanDomain(raw);
1142	  if (domain.length < 4) return { ok: false, error: "Domain is too short." };
1143	  if (domain.length > 253) return { ok: false, error: "Domain is too long." };
1144	  if (IP_RE.test(domain)) return { ok: false, error: "Enter a domain name, not an IP address." };
1145	  if (!HOSTNAME_RE.test(domain)) return { ok: false, error: "Invalid domain format. Example: play.mydomain.com" };
1146	  return { ok: true, domain };
1147	}
