1149	/** Resolve the effective public IP and game port for a server. */
1150	async function serverConnectInfo(serverId: string): Promise<{ ip: string; port: number } | null> {
1151	  const s = await db.server.findUnique({
1152	    where: { id: serverId },
1153	    select: {
1154	      dedicatedIp: { select: { address: true } },
1155	      portForwards: true,
1156	      osTemplate: { select: { family: true } },
1157	      gamePlan: { select: { gameFamily: true } },
1158	    },
1159	  });
1160	  if (!s) return null;
1161	
1162	  const publicIp = process.env.PUBLIC_IP ?? "";
1163	
1164	  // Match the port forward that actually serves the game's own port, not just
1165	  // whichever one sorts first — a customer can add extra forwards (RCON web
1166	  // UI, Dynmap, a Bedrock/Geyser port, ...) that must never be mistaken for
1167	  // the game's real connect port here, since this result gates
1168	  // `customDomainVerified`. Falls back to the first forward if none matches
1169	  // (e.g. an unrecognized family) rather than reporting no connect info at all.
1170	  const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family) as GameFamily | undefined;
1171	  const expectedPort = family ? GAME_PORT[family]?.port : undefined;
1172	  const gameForward = s.portForwards.find((f) => f.guestPort === expectedPort) ?? s.portForwards[0];
1173	  const defaultPort = expectedPort ?? 25565;
1174	
1175	  if (s.dedicatedIp) {
1176	    // Dedicated IP has no NAT translation — the guest's own game port is what
1177	    // players (and DNS) actually connect to.
1178	    return { ip: s.dedicatedIp.address, port: gameForward?.guestPort ?? defaultPort };
1179	  }
1180	
1181	  if (gameForward) {
1182	    return { ip: publicIp, port: gameForward.publicPort };
1183	  }
1184	
1185	  return publicIp ? { ip: publicIp, port: defaultPort } : null;
1186	}
