143	// ===========================================================================
144	// Real install/remove — per-source adapters over SSH.
145	//
146	// Approach: the worker resolves a DIRECT download URL from the source's API, then
147	// SSHes into the game VM and has the VM itself `curl` the file into the game's
148	// plugin/mod directory (deterministic filename, so uninstall is a plain rm — no
149	// per-install state to track). Sources that need auth or per-repo handling
150	// (GitHub release zips, Nexus, CurseForge key, Codefling paid) soft-fail with a
151	// clear "install manually from <url>" note rather than faking success.
152	//
153	// Supported today: modrinth + spigotmc (Minecraft), umod (Rust), thunderstore
154	// (Valheim) — which fully covers those three games' catalogs.
155	// ===========================================================================
156	
157	type ModResult = { ok: boolean; version?: string; error?: string };
158	type ModRow = {
159	  gameFamily: string;
160	  source: string;
161	  sourceId: string | null;
162	  slug: string;
163	  name: string;
164	  url: string | null;
165	};
166	type SshServer = {
167	  id: string;
168	  rootPassword: string | null;
169	  rootPasswordEnc?: string | null;
170	  sshPort: number | null;
171	  dedicatedIp?: { address: string } | null;
172	};
173	
174	const CONNECT_TIMEOUT_MS = 15_000;
175	const EXEC_TIMEOUT_MS = 200_000; // downloads can be large
176	
177	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
178	function pascal(name: string): string {
179	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
180	  return p || "Plugin";
181	}
182	
183	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
184	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
185	  switch (mod.source) {
186	    case "modrinth":
187	    case "spigotmc":
188	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
189	    case "umod":
190	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
191	    case "thunderstore":
192	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
193	    default:
194	      return null; // github / nexus / curseforge / codefling / hangar — manual
195	  }
196	}
197	
198	/** Resolve a direct download URL from the source's API (worker-side). */
199	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
200	  const id = mod.sourceId ?? "";
201	  try {
202	    switch (mod.source) {
203	      case "umod":
204	        return `https://umod.org/plugins/${id}.cs`;
205	      case "spigotmc":
206	        return `https://api.spiget.org/v2/resources/${id}/download`;
207	      case "modrinth": {
208	        const loader = modrinthLoader(mod);
209	        const q = loader ? `?loaders=["${loader}"]` : "";
210	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
211	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
212	        });
213	        if (!res.ok) return null;
214	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
215	        const v = versions[0];
216	        if (!v) return null;
217	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
218	      }
219	      case "thunderstore": {
220	        const [author, ...rest] = id.split("-");
221	        if (!rest.length) return null;
222	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
223	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
224	        });
225	        if (!res.ok) return null;
226	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
227	        return pkg.latest?.download_url ?? null;
228	      }
229	      default:
230	        return null;
231	    }
232	  } catch (e) {
233	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
234	    return null;
235	  }
236	}
237	
238	function modrinthLoader(mod: ModRowFull): string | null {
239	  // Prefer the mod's own loader target; fall back to the server's variant.
240	  const key = mod.appliesTo ?? mod.variant ?? "";
241	  const map: Record<string, string> = {
242	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
243	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
244	  };
245	  return map[key] ?? null;
246	}
247	
248	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
249	function modDirShell(family: string, variant: string | null): string | null {
250	  switch (family) {
251	    case "minecraft": {
252	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
253	      const sub = modded ? "mods" : "plugins";
254	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
255	    }
256	    case "rust":
257	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
258	    case "valheim":
259	      return `d=$(find /opt /srv /home -maxdepth 9 -type d -name BepInEx 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
260	    default:
261	      return null;
262	  }
263	}
264	
265	const shq = (s: string) => s.replace(/'/g, "'\\''");
266	
267	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
268	  const target = planTarget(mod);
269	  if (!target) {
270	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
271	  }
272	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
273	  if (!dirShell) {
274	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
275	  }
276	  const url = await resolveUrl(mod);
277	  if (!url) return { ok: false, error: "Could not resolve a download for this mod (it may have moved)." };
278	
279	  let cmd: string;
280	  if (target.kind === "zip") {
281	    cmd =
282	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
283	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
284	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
285	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
286	  } else {
287	    cmd =
288	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
289	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
290	  }
291	
292	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
293	  const s = out.stdout.trim();
294	  if (s.endsWith("OK")) return { ok: true };
295	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
296	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
297	  return { ok: false, error: "Download failed on the server." };
298	}
299	
300	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
301	  const target = planTarget(mod);
302	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
303	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
304	  const rm =
305	    target.kind === "zip"
306	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
307	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
308	  await withSsh(server, (conn) => execRemote(conn, rm));
309	  return { ok: true };
310	}
311	
312	// --- SSH transport (root@VM, password from the same source as the file manager) ---
313	
314	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
315	
316	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
317	  return new Promise((resolve, reject) => {
318	    const t = connectionTarget(server as any);
319	    if (!t) return reject(new Error("server is not reachable yet"));
320	    const password = serverRootPassword(server as any);
321	    if (!password) return reject(new Error("server has no root password set"));
322	    const conn = new Client();
323	    let settled = false;
324	    const finish = (err: Error | null, val?: T) => {
325	      if (settled) return;
326	      settled = true;
327	      try { conn.end(); } catch { /* best-effort */ }
328	      err ? reject(err) : resolve(val as T);
329	    };
330	    conn.on("ready", () => {
331	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
332	    });
333	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
334	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
335	  });
336	}
337	
338	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
339	  return new Promise((resolve, reject) => {
340	    conn.exec(cmd, (err, stream: ClientChannel) => {
341	      if (err) return reject(err);
342	      let stdout = "";
343	      let stderr = "";
344	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
345	      stream
346	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
347	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
348	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
349	    });
350	  });
351	}
