52	export async function gameConfigApply(job: Job): Promise<void> {
53	  const serverId = job.serverId;
54	  if (!serverId) throw new Error("game config: job has no serverId");
55	
56	  const server = await db.server.findUnique({
57	    where: { id: serverId },
58	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true },
59	  });
60	  if (!server) throw new Error(`Server ${serverId} not found`);
61	
62	  const family = familyFor(server);
63	  const schema = schemaFor(family);
64	  if (!family || !schema) {
65	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
66	  }
67	
68	  const variant = server.gameVariant ?? schema.defaultVariant;
69	
70	  // -------------------------------------------------------------------------
71	  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
72	  //
73	  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
74	  // customer request fell through to the block below, stamped an `_appliedAt`
75	  // marker, and notified them "Game settings applied on <hostname>" — with the
76	  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
77	  // customer changed their difficulty or slot count, was told it was applied, and
78	  // nothing on the server had changed.
79	  //
80	  // Identical in kind to the SSL bug fixed the same day, where production wrote a
81	  // certificate row as ACTIVE with an invented expiry while no certbot had run:
82	  // the system asserting an outcome it never performed. A change we did not apply
83	  // is a FAILURE, and it must say so loudly enough that an operator notices the
84	  // flag is missing.
85	  // -------------------------------------------------------------------------
86	  if (!REAL_APPLY_ENABLED && !SANDBOX) {
87	    throw new Error(
88	      "Game settings could not be applied: real application is switched off on this " +
89	        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
90	        "server and your settings are NOT in effect. Please contact support."
91	    );
92	  }
93	
94	  if (!REAL_APPLY_ENABLED) {
95	    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
96	    const marker = {
97	      _appliedVariant: variant,
98	      _appliedAt: new Date().toISOString(),
99	      _configVersion: GAME_CONFIG_VERSION,
100	      _sandbox: SANDBOX,
101	    };
102	
103	    await db.server.update({
104	      where: { id: server.id },
105	      data: { gameConfig: { ...existing, ...marker } as any },
106	    });
107	
108	    await notify(
109	      server.userId,
110	      `Game settings applied on ${server.hostname}`,
111	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
112	      `/dashboard/servers/${server.id}?tab=game settings`
113	    );
114	    return;
115	  }
116	
117	  // -------------------------------------------------------------------------
118	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
119	  // a failure notifies the user but never throws out of the handler.
120	  // -------------------------------------------------------------------------
121	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
122	  const valid = validateConfig(family, existing);
123	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
124	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
125	  const values = valid.ok ? valid.values : {};
126	
127	  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
128	  try {
129	    outcome = await applyRealConfig(server, family, values);
130	  } catch (e) {
131	    const msg = e instanceof Error ? e.message : String(e);
132	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
133	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
134	  }
135	
136	  // Always record the applied-marker (even on partial/soft failure) so the portal
137	  // reflects the attempt, and note whether the real push succeeded.
138	  const marker = {
139	    _appliedVariant: variant,
140	    _appliedAt: new Date().toISOString(),
141	    _configVersion: GAME_CONFIG_VERSION,
142	    _sandbox: SANDBOX,
143	    _real: true,
144	    _realOk: outcome.ok,
145	  };
146	  try {
147	    await db.server.update({
148	      where: { id: server.id },
149	      data: { gameConfig: { ...existing, ...marker } as any },
150	    });
151	  } catch (e) {
152	    console.error("[game-config] marker update failed", e);
153	  }
154	
155	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
156	  await notify(
157	    server.userId,
158	    outcome.ok
159	      ? `Game settings applied on ${server.hostname}`
160	      : `Game settings partially applied on ${server.hostname}`,
161	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
162	    `/dashboard/servers/${server.id}?tab=game settings`
163	  );
164	}
