304	/** Dispatch to the correct family renderer. */
305	async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
306	  return withSsh(server, async (conn, sftp) => {
307	    switch (family) {
308	      case "minecraft":
309	        return applyMinecraft(conn, sftp, values);
310	      case "rust":
311	        return applyRust(conn, sftp, values);
312	      case "valheim":
313	        return applyValheim(conn, sftp, values);
314	      case "cs2":
315	        return applyCs2(conn, sftp, values);
316	      case "palworld":
317	        return applyPalworld(conn, sftp, values);
318	      default:
319	        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
320	    }
321	  });
322	}
