515	
516	async function applyRust(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
517	  // Rust reads server.cfg from <identity>/cfg/server.cfg — the identity dir is
518	  // deployment-specific, so we locate it rather than guessing.
519	  // TODO(paths): confirm the server identity/install path for the Rust image.
520	  const path = await remoteLocate(
521	    conn,
522	    ["/opt/rust/server/rustserver/cfg/server.cfg", "/opt/rust/server/cfg/server.cfg", "/home/rust/server/rustserver/cfg/server.cfg"],
523	    ["/opt/rust", "/home/rust", "/home/steam", "/opt"],
524	    "server.cfg"
525	  );
526	  if (!path) {
527	    return { ok: false, applied: [], notes: ["Could not locate Rust server.cfg — nothing was changed."] };
528	  }
529	  const existing = await sftpRead(sftp, path);
530	  if (existing == null) {
531	    return { ok: false, applied: [], notes: [`server.cfg disappeared at ${path} — nothing was changed.`] };
532	  }
533	
534	  // Field keys map to `server.<key>` convars; strings are quoted.
535	  const updates: Record<string, string> = {};
536	  for (const [key, val] of Object.entries(v)) {
537	    const convar = `server.${key}`;
538	    if (typeof val === "boolean") updates[convar] = bool(val);
539	    else if (typeof val === "number") updates[convar] = String(val);
540	    else updates[convar] = `"${String(val).replace(/"/g, '\\"')}"`;
541	  }
542	  const next = updateConvars(existing, updates);
543	  await sftpWrite(sftp, path, next);
544	
545	  // Rust RCON is a WebSocket (rcon.web) protocol — not attempted here.
546	  // TODO(rcon): push live convars (hostname/maxplayers/pve) via the Rust
547	  // WebSocket RCON if the server exposes it. For now note a restart/wipe.
548	  return {
549	    ok: true,
550	    applied: [`Wrote ${Object.keys(updates).length} convar(s) to ${path}.`],
551	    notes: ["Restart the server to apply. World-size/seed changes only take effect on the next map wipe."],
552	  };
553	}
