559	async function applyValheim(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
560	  // Valheim settings are launch args (-world/-preset/-public/-password), not a
561	  // config file, so the exact wiring depends on the start script / systemd unit.
562	  // TODO(valheim): point the start script/systemd unit at the args file we write
563	  // below (or template the unit directly). We deliberately do NOT rewrite the
564	  // start script here — that would risk clobbering a script we can't parse.
565	  const parts: string[] = [];
566	  if (v["world"] != null) parts.push(`-world "${String(v["world"]).replace(/"/g, "")}"`);
567	  if (v["preset"] != null) parts.push(`-preset ${String(v["preset"])}`);
568	  if (v["public"] != null) parts.push(`-public ${bool(v["public"]) === "true" ? "1" : "0"}`);
569	  if (v["password"] != null && String(v["password"]).length > 0) {
570	    parts.push(`-password "${String(v["password"]).replace(/"/g, "")}"`);
571	  }
572	  const args = parts.join(" ");
573	
574	  // Find a Valheim install dir to drop the args file next to.
575	  const dir = await remoteLocate(
576	    conn,
577	    [],
578	    ["/opt/valheim", "/home/valheim", "/home/steam/valheim", "/opt"],
579	    "valheim_server.x86_64"
580	  );
581	  if (!dir) {
582	    return {
583	      ok: false,
584	      applied: [],
585	      notes: ["Could not locate the Valheim install — launch args were not written. Restart with the new args once the install path is known."],
586	    };
587	  }
588	  const targetDir = dir.replace(/\/[^/]*$/, "");
589	  const argsFile = `${targetDir}/nxeon-launch-args.txt`;
590	  await sftpWrite(sftp, argsFile, args + "\n");
591	
592	  return {
593	    ok: true,
594	    applied: [`Wrote launch args to ${argsFile}.`],
595	    notes: ["Wire the start script/systemd unit to source this file, then restart the server. Password/world changes require a restart."],
596	  };
597	}
