719	      "/opt/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
720	      "/home/steam/Steam/steamapps/common/PalServer/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
721	      "/home/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
722	    ],
723	    ["/opt/palworld", "/home/steam", "/home/palworld", "/opt"],
724	    "PalWorldSettings.ini"
725	  );
726	  if (!path) {
727	    return { ok: false, applied: [], notes: ["Could not locate PalWorldSettings.ini — nothing was changed."] };
728	  }
729	  const existing = await sftpRead(sftp, path);
730	  if (existing == null) {
731	    return { ok: false, applied: [], notes: [`PalWorldSettings.ini disappeared at ${path} — nothing was changed.`] };
732	  }
733	
734	  // Schema field keys → PalWorldSettings OptionSettings keys.
735	  const updates: Record<string, string> = {};
