8	function fmt(bytes: number): string {
9	  if (bytes < 1024) return `${bytes} B`;
10	  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
11	  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
12	  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
13	}
