6	/**
7	 * Mod Store — the panel's differentiator. An App-Store-style browse experience
8	 * over the per-game mod/plugin catalog (GameMod), with a detail view and a
9	 * version → confirm install flow.
10	 *
11	 * REAL backend: catalog + install state + install/uninstall come from
12	 * lib/actions-mods.ts (state-driven GAME_MOD_SYNC job). DERIVED/illustrative
13	 * (clearly labelled in the UI): star rating, install counts, screenshots,
14	 * version history, reviews and changelog — the GameMod model has no such fields
15	 * yet, so they are computed deterministically from the mod's slug so the
16	 * storefront feels alive. The version dropdown is display-only: the installer
17	 * always applies the latest compatible build (see the note in the install modal).
18	 *
19	 * `scope="plugins"` reframes the same catalog toward loader plugins (admin,
20	 * protection, economy, chat, permissions…), falling back to the full catalog
21	 * with a note when a family draws no plugin categories.
22	 */
23	
24	const PLUGIN_KEYWORDS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport"];
