26	// ---- deterministic "storefront" meta (illustrative, derived from slug) ----
27	function hash(s: string): number {
28	  let h = 2166136261;
29	  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
30	  return h >>> 0;
31	}
32	function ratingFor(m: CatalogMod): number {
33	  return 4 + ((hash(m.slug) % 11) / 10); // 4.0 – 5.0
34	}
35	function installsFor(m: CatalogMod): number {
36	  const base = 800 + (hash(m.slug) % 90000);
37	  return m.featured ? base * 4 + 120000 : base;
38	}
39	function fmtInstalls(n: number): string {
40	  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
41	  return String(n);
42	}
43	function versionsFor(m: CatalogMod): string[] {
44	  const h = hash(m.slug);
45	  const major = 1 + (h % 4);
46	  const minor = h % 12;
47	  return [`Latest (v${major}.${minor})`, `v${major}.${Math.max(0, minor - 1)}`, `v${major - 1 >= 1 ? major - 1 : 1}.9`];
48	}
49	function reviewsFor(m: CatalogMod): { author: string; stars: number; body: string }[] {
50	  const h = hash(m.slug);
51	  const authors = ["RustLegend", "AdminAce", "SurvivalKing", "ModHoarder", "PvPMaster"];
52	  return [
53	    { author: authors[h % authors.length], stars: 5, body: "Rock solid — installed in one click and it just worked on our server." },
54	    { author: authors[(h >> 3) % authors.length], stars: 4, body: "Great feature set. Slight config learning curve but well worth it." },
55	  ];
56	}
