29	function parsePlan(raw?: string | null): { cmd: string; intent?: string }[] {
30	  if (!raw) return [];
31	  try {
32	    const p = JSON.parse(raw);
33	    if (Array.isArray(p)) return p.map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent })).filter((s) => s.cmd);
34	  } catch {
35	    /* ignore */
36	  }
37	  return [];
38	}
