55	    return () => { alive = false; };
56	  }, []);
57	
58	  useEffect(() => {
59	    if (!buildId) return;
60	    let alive = true;
61	    let timer: ReturnType<typeof setTimeout>;
62	    const tick = async () => {
63	      try {
64	        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
65	        if (res.ok) {
