113	        style={{ background: "radial-gradient(circle, rgba(34,211,238,0.4), transparent 70%)" }}
114	      />
115	      <div className="relative flex items-center gap-2">
116	        <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-accent-cyan/30 to-brand-500/30 text-base" aria-hidden>
117	          ✦
118	        </span>
119	        <div>
120	          <h2 className="text-lg font-semibold">Build with AI</h2>
121	          <p className="text-sm text-slate-400">Describe the outcome — Claude plans it, you approve, we run it on your {gameLabel} server.</p>
122	        </div>
123	        {locked && (
