128	      </div>
129	
130	      {locked && (
131	        <div className="relative mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-500/25 bg-amber-500/[0.06] px-4 py-3">
132	          <p className="text-sm text-amber-200">
133	            Connect an Anthropic API key or authenticate your Claude subscription to unlock Build with AI.
134	          </p>
135	          <a href="/dashboard/settings" className="btn-secondary shrink-0 text-xs">
136	            Connect in Settings
137	          </a>
138	        </div>
