140	
141	      <div className={`relative mt-4 flex flex-wrap gap-2 ${locked ? "pointer-events-none" : ""}`}>
142	        {presetsFor(gameLabel).map((p) => (
143	          <button
144	            key={p}
145	            onClick={() => setPrompt(p)}
146	            disabled={inProgress}
147	            className="rounded-full border border-white/[0.08] bg-white/[0.03] px-3 py-1.5 text-xs text-slate-300 transition-colors hover:border-brand-400/40 hover:text-white disabled:opacity-40"
148	          >
149	            {p}
