160	        className="input mt-3 w-full resize-y"
161	      />
162	      {error && <p className="mt-2 text-xs text-red-400">{error}</p>}
163	
164	      <div className="mt-3 flex items-center gap-2">
165	        <button className="btn-primary disabled:opacity-40" disabled={inProgress || pending || locked || prompt.trim().length < 8} onClick={submit}>
166	          {inProgress ? "Working…" : "Build it"}
167	        </button>
