19	export function GameRoles({ serverId, running }: { serverId: string; running: boolean }) {
20	  const [status, setStatus] = useState<"checking" | "not-installed" | "needs-setup" | "ready">("checking");
21	  const [roles, setRoles] = useState<GameRole[] | null>(null);
22	  const [selected, setSelected] = useState<string | null>(null);
23	  const [err, setErr] = useState<string | null>(null);
24	  const [msg, setMsg] = useState<string | null>(null);
25	  const [pending, start] = useTransition();
26	
27	  useEffect(() => {
28	    if (!running) return;
29	    start(async () => {
30	      const r = await detectGameLuckPerms(serverId);
31	      if (!r.ok) { setErr(r.error); return; }
32	      if (!r.installed) { setStatus("not-installed"); return; }
33	      if (!r.hasYamlStorage) { setStatus("needs-setup"); return; }
34	      setStatus("ready");
35	      const lr = await listGameRoles(serverId);
36	      if (lr.ok) {
37	        setRoles(lr.roles);
38	        setSelected(lr.roles[0]?.name ?? null);
39	      }
40	    });
41	  }, [running, serverId]);
42	
43	  function refresh() {
44	    start(async () => {
45	      setErr(null); setMsg(null);
46	      const lr = await listGameRoles(serverId);
47	      if (lr.ok) {
48	        setRoles(lr.roles);
49	        setSelected((cur) => (cur && lr.roles.some((r) => r.name === cur) ? cur : (lr.roles[0]?.name ?? null)));
50	      } else setErr(lr.error);
51	    });
52	  }
53	
54	  function doSetup() {
55	    start(async () => {
56	      setErr(null);
57	      const r = await ensureGameLpYamlStorage(serverId);
58	      if (r.ok) { setStatus("ready"); refresh(); }
59	      else setErr(r.error);
60	    });
