63	  if (!running) return <div className="card text-sm text-slate-500">Start the server to manage roles.</div>;
64	
65	  if (status === "checking") return <div className="card text-sm text-slate-500">Checking for LuckPerms…</div>;
66	
67	  if (status === "not-installed") {
68	    return (
