73	          LuckPerms lets you create roles, assign players, and control exactly which commands each role can use.
74	        </p>
75	      </div>
76	    );
77	  }
78	
79	  if (status === "needs-setup") {
80	    return (
81	      <div className="card">
82	        <h3 className="font-semibold">Roles & Permissions</h3>
83	        <p className="mt-2 text-sm text-slate-400">
