104	        onRefresh={refresh}
105	        pending={pending}
106	        start={start}
107	        setErr={setErr}
108	        setMsg={setMsg}
109	      />
110	      {err && <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{err}</div>}
111	      {msg && <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-400">{msg}</div>}
112	      {active && (
113	        <>
114	          <PermissionsPanel
115	            serverId={serverId}
