138	function RolesList({
139	  roles, selected, onSelect, serverId, onRefresh, pending, start, setErr, setMsg,
140	}: {
141	  roles: GameRole[]; selected: string | null; onSelect: (n: string) => void;
142	  serverId: string; onRefresh: () => void; pending: boolean;
143	  start: (fn: () => Promise<void>) => void;
144	  setErr: (e: string | null) => void; setMsg: (m: string | null) => void;
145	}) {
146	  const [newName, setNewName] = useState("");
147	
148	  function add() {
149	    const name = newName.trim().toLowerCase();
150	    if (!name) return;
151	    start(async () => {
152	      setErr(null); setMsg(null);
153	      const r = await createGameRole(serverId, name);
154	      if (r.ok) { setMsg(`Created role "${name}"`); setNewName(""); onRefresh(); }
155	      else setErr(r.error);
156	    });
157	  }
158	
159	  function del(name: string) {
160	    if (!window.confirm(`Delete role "${name}"? This removes all permissions and player assignments.`)) return;
161	    start(async () => {
162	      setErr(null); setMsg(null);
163	      const r = await deleteGameRole(serverId, name);
164	      if (r.ok) { setMsg(`Deleted role "${name}"`); onRefresh(); }
165	      else setErr(r.error);
166	    });
167	  }
168	
169	  return (
170	    <div className="card">
171	      <div className="flex items-center justify-between">
172	        <div>
173	          <h3 className="font-semibold">Roles</h3>
174	          <p className="mt-0.5 text-sm text-slate-400">Create roles, then assign commands and players below.</p>
175	        </div>
176	        <button className="btn-ghost text-xs" onClick={onRefresh} disabled={pending}>Refresh</button>
177	      </div>
178	
179	      <div className="mt-4 flex gap-2">
180	        <input
181	          className="input flex-1"
182	          placeholder="New role name (lowercase)"
183	          value={newName}
184	          onChange={(e) => setNewName(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ""))}
185	          onKeyDown={(e) => e.key === "Enter" && add()}
186	          disabled={pending}
187	          maxLength={20}
188	        />
189	        <button className="btn-primary" onClick={add} disabled={pending || !newName.trim()}>Create</button>
190	      </div>
191	
192	      {roles.length === 0 ? (
193	        <p className="mt-4 text-sm text-slate-500">No roles yet. Create one to get started.</p>
194	      ) : (
195	        <div className="mt-4 flex flex-wrap gap-2">
196	          {roles.map((role) => (
197	            <div key={role.name} className="group flex items-center gap-1">
198	              <button
199	                className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
200	                  selected === role.name
201	                    ? "bg-brand-500/20 text-brand-300 ring-1 ring-inset ring-brand-500/40"
202	                    : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
203	                }`}
204	                onClick={() => onSelect(role.name)}
205	                disabled={pending}
206	              >
207	                {role.name}
208	                <span className="ml-1.5 text-xs text-slate-500">{role.members.length}</span>
209	              </button>
210	              <button
211	                className="hidden text-xs text-red-400 hover:text-red-300 group-hover:inline-block"
212	                onClick={() => del(role.name)}
213	                disabled={pending}
214	                title="Delete role"
215	              >
216	                x
217	              </button>
218	            </div>
219	          ))}
220	        </div>
221	      )}
222	    </div>
223	  );
224	}
