226	function PermissionsPanel({
227	  serverId, role, onRefresh, pending, start, setErr, setMsg,
228	}: {
229	  serverId: string; role: GameRole; onRefresh: () => void; pending: boolean;
230	  start: (fn: () => Promise<void>) => void;
231	  setErr: (e: string | null) => void; setMsg: (m: string | null) => void;
232	}) {
233	  const byPlugin = new Map<string, typeof FREEMC_GATEABLE_COMMANDS>();
234	  for (const cmd of FREEMC_GATEABLE_COMMANDS) {
235	    const list = byPlugin.get(cmd.plugin) ?? [];
236	    list.push(cmd);
237	    byPlugin.set(cmd.plugin, list);
238	  }
239	
240	  function toggle(node: string, currentlyGranted: boolean) {
241	    start(async () => {
242	      setErr(null); setMsg(null);
243	      const r = await setGameRolePermission(serverId, role.name, node, !currentlyGranted);
244	      if (r.ok) { setMsg(`${!currentlyGranted ? "Granted" : "Revoked"} permission`); onRefresh(); }
245	      else setErr(r.error);
246	    });
247	  }
248	
249	  return (
250	    <div className="card">
251	      <h3 className="font-semibold">
252	        Permissions for <span className="text-brand-300">{role.name}</span>
253	      </h3>
254	      <p className="mt-0.5 text-sm text-slate-400">
255	        Toggle which commands players in this role can use in-game.
256	      </p>
257	
258	      <div className="mt-4 space-y-5">
259	        {[...byPlugin.entries()].map(([plugin, cmds]) => (
260	          <div key={plugin}>
261	            <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{plugin}</p>
262	            <div className="mt-2 space-y-1">
263	              {cmds.map((cmd) => {
264	                const granted = role.permissions.includes(cmd.node);
265	                return (
266	                  <label key={cmd.node} className="flex cursor-pointer items-center gap-3 rounded-lg px-2 py-1.5 hover:bg-white/[0.03]">
267	                    <input
268	                      type="checkbox"
269	                      checked={granted}
270	                      onChange={() => toggle(cmd.node, granted)}
271	                      disabled={pending}
272	                      className="accent-brand-500"
273	                    />
274	                    <span className="text-sm text-slate-200">{cmd.label}</span>
275	                  </label>
276	                );
277	              })}
278	            </div>
279	          </div>
280	        ))}
281	      </div>
282	    </div>
283	  );
284	}
