286	function MembersPanel({
287	  serverId, role, onRefresh, pending, start, setErr, setMsg,
288	}: {
289	  serverId: string; role: GameRole; onRefresh: () => void; pending: boolean;
290	  start: (fn: () => Promise<void>) => void;
291	  setErr: (e: string | null) => void; setMsg: (m: string | null) => void;
292	}) {
293	  const [input, setInput] = useState("");
294	
295	  function add() {
296	    const name = input.trim();
297	    if (!PLAYER_NAME_RE.test(name)) return;
298	    start(async () => {
299	      setErr(null); setMsg(null);
300	      const r = await assignGameRolePlayer(serverId, role.name, name);
301	      if (r.ok) { setMsg(`Added ${name} to ${role.name}`); setInput(""); onRefresh(); }
302	      else setErr(r.error);
303	    });
304	  }
305	
306	  function remove(name: string) {
307	    start(async () => {
308	      setErr(null); setMsg(null);
309	      const r = await removeGameRolePlayer(serverId, role.name, name);
310	      if (r.ok) { setMsg(`Removed ${name} from ${role.name}`); onRefresh(); }
311	      else setErr(r.error);
312	    });
313	  }
314	
315	  return (
316	    <div className="card">
317	      <h3 className="font-semibold">
318	        Players in <span className="text-brand-300">{role.name}</span>
319	      </h3>
320	      <p className="mt-0.5 text-sm text-slate-400">
321	        Players assigned to this role get all permissions toggled above.
322	      </p>
323	
324	      <div className="mt-4 flex gap-2">
325	        <input
326	          className="input flex-1"
327	          placeholder="Player name"
328	          value={input}
329	          onChange={(e) => setInput(e.target.value)}
330	          onKeyDown={(e) => e.key === "Enter" && add()}
331	          disabled={pending}
332	        />
333	        <button className="btn-primary" onClick={add} disabled={pending || !input.trim()}>Add</button>
334	      </div>
