134	function Field({
135	  field,
136	  value,
137	  disabled,
138	  onChange,
139	}: {
140	  field: ConfigField;
141	  value: string | number | boolean | undefined;
142	  disabled?: boolean;
143	  onChange: (v: string | number | boolean) => void;
144	}) {
145	  const isMissing = !!field.required && String(value ?? field.default ?? "").trim() === "";
146	  const labelRow = (
147	    <span className="mb-1.5 flex items-baseline justify-between gap-2">
148	      <span className="font-medium">{field.label}</span>
149	      {field.required ? (
150	        <span
151	          className={`text-[10px] font-semibold uppercase tracking-wide ${isMissing ? "text-red-300" : "text-emerald-400"}`}
152	        >
153	          {isMissing ? "Required — server won't start without this" : "Required ✓"}
154	        </span>
155	      ) : (
156	        field.phase === "deploy" && (
157	          <span className="text-[10px] uppercase tracking-wide text-amber-300/80">restart</span>
158	        )
159	      )}
160	    </span>
161	  );
162	
163	  if (field.type === "bool") {
164	    const on = value === true;
165	    return (
166	      <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-3">
167	        <span className="text-sm">
168	          <span className="font-medium">{field.label}</span>
169	          {field.help && <span className="mt-0.5 block text-xs text-slate-500">{field.help}</span>}
170	        </span>
171	        <button
172	          type="button"
173	          role="switch"
174	          aria-checked={on}
175	          disabled={disabled}
176	          onClick={() => onChange(!on)}
177	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
178	            on ? "bg-brand-500" : "bg-white/15"
179	          } ${disabled ? "opacity-60" : ""}`}
180	        >
181	          <span
182	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
183	              on ? "translate-x-5" : "translate-x-0.5"
184	            }`}
185	          />
186	        </button>
187	      </div>
188	    );
189	  }
190	
191	  return (
192	    <label className="block text-sm">
193	      {labelRow}
194	      {field.type === "enum" ? (
195	        <select
196	          className="input"
197	          value={String(value ?? field.default)}
198	          disabled={disabled}
199	          onChange={(e) => onChange(e.target.value)}
200	        >
201	          {field.options?.map((o) => (
202	            <option key={o.value} value={o.value}>
203	              {o.label}
204	            </option>
205	          ))}
206	        </select>
207	      ) : field.type === "int" ? (
208	        <input
209	          className="input"
210	          type="number"
211	          value={value === undefined || value === null ? Number(field.default) : Number(value)}
212	          min={field.min}
213	          max={field.max}
214	          step={1}
215	          disabled={disabled}
216	          onChange={(e) => onChange(e.target.value === "" ? "" as any : Number(e.target.value))}
217	        />
218	      ) : (
219	        <input
220	          className={`input ${isMissing ? "border-red-400/60 focus:border-red-400" : ""}`}
221	          type="text"
222	          value={String(value ?? field.default)}
223	          maxLength={256}
224	          disabled={disabled}
225	          aria-invalid={isMissing}
226	          onChange={(e) => onChange(e.target.value)}
227	        />
228	      )}
229	      {field.help && (
230	        <span className={`mt-1 block text-xs ${isMissing ? "text-red-300" : "text-slate-500"}`}>{field.help}</span>
231	      )}
232	    </label>
233	  );
234	}
