79	/** Best-effort live status, bounded to a few seconds regardless of what
80	 *  freemc-host is doing — a public marketing page must never hang or fail
81	 *  because of it. Returns null (rendered as "status unknown") on any timeout,
82	 *  SSH error, or if the host row itself is missing. */
83	async function getLiveStatusBestEffort(containerName: string): Promise<{ running: boolean; players: { online: number; max: number } | null } | null> {
84	  const withTimeout = <T,>(p: Promise<T>, ms: number): Promise<T> =>
85	    new Promise((resolve, reject) => {
86	      const t = setTimeout(() => reject(new Error("timeout")), ms);
87	      p.then((v) => { clearTimeout(t); resolve(v); }, (e) => { clearTimeout(t); reject(e); });
88	    });
89	
90	  try {
91	    const host = await db.server.findFirst({
92	      where: { hostname: "freemc-host" },
93	      select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
94	    });
95	    if (!host) return null;
96	    return await withTimeout(
97	      withServerSsh(host, (conn) => getFreeServerStatus(conn, containerName)),
98	      4_000,
99	    );
100	  } catch {
101	    return null;
102	  }
103	}
